{"code":"import pandas as pd
import numpy as np

raw = pd.read_csv('raw_responses.csv')
out = pd.read_csv('pipeline_output.csv')

# Let's write a python script to test our understanding and compare column by column.

def score_phq9(df):
    totals = []
    bands = []
    prorateds = []
    flags = []

    q_cols = [f'phq9_{i}' for i in range(1, 10)]

    for idx, row in df.iterrows():
        # self harm flag
        q9 = row['phq9_9']
        if pd.isna(q9) or q9 == -9 or q9 < 0 or q9 > 3:
            flags.append(None)
        else:
            flags.append(q9 in [1, 2, 3])

        # check valid answers for total
        answers = []
        skipped = 0
        for col in q_cols:
            val = row[col]
            if pd.isna(val) or val == -9 or val < 0 or val > 3:
                skipped += 1
            else:
                answers.append(val)

        if skipped >= 2:
            totals.append(None)
            bands.append(None)
            prorateds.append(None)
        elif skipped == 1:
            # sum * 9 / 8, round half up
            s = sum(answers)
            # rounding half up: decimal >= 0.5 rounds up
            raw_val = (s * 9.0) / 8.0
            # in python, round(x) rounds to nearest even. Let's do proper half up:
            # floor(x + 0.5)
            tot = int(np.floor(raw_val + 0.5))
            totals.append(tot)
            prorateds.append(True)
            bands.append(get_phq9_band(tot))
        else:
            tot = sum(answers)
            totals.append(tot)
            prorateds.append(False)
            bands.append(get_phq9_band(tot))

    return pd.DataFrame({
        'phq9_total': totals,
        'phq9_band': bands,
        'phq9_prorated': prorateds,
        'phq9_self_harm_flag': flags
    })

def get_phq9_band(tot):
    if tot <= 4:
        return 'none-minimal'
    elif tot <= 9:
        return 'mild'
    elif tot <= 14:
        return 'moderate'
    elif tot <= 19:
        return 'moderately severe'
    else:
        return 'severe'

def score_gad7(df):
    totals = []
    bands = []
    prorateds = []
    q_cols = [f'gad7_{i}' for i in range(1, 8)]

    for idx, row in df.iterrows():
        answers = []
        skipped = 0
        for col in q_cols:
            val = row[col]
            if pd.isna(val) or val == -9 or val < 0 or val > 3:
                skipped += 1
            else:
                answers.append(val)

        if skipped >= 2:
            totals.append(None)
            bands.append(None)
            prorateds.append(None)
        elif skipped == 1:
            raw_val = (sum(answers) * 7.0) / 6.0
            tot = int(np.floor(raw_val + 0.5))
            totals.append(tot)
            prorateds.append(True)
            bands.append(get_gad7_band(tot))
        else:
            tot = sum(answers)
            totals.append(tot)
            prorateds.append(False)
            bands.append(get_gad7_band(tot))

    return pd.DataFrame({
        'gad7_total': totals,
        'gad7_band': bands,
        'gad7_prorated': prorateds
    })

def get_gad7_band(tot):
    if tot <= 4:
        return 'minimal'
    elif tot <= 9:
        return 'mild'
    elif tot <= 14:
        return 'moderate'
    else:
        return 'severe'

def score_rses(df):
    totals = []
    prorateds = []
    reverse_items = [3, 5, 8, 9, 10]

    for idx, row in df.iterrows():
        answers = []
        skipped = 0
        for i in range(1, 11):
            col = f'rses_{i}'
            val = row[col]
            if pd.isna(val) or val == -9 or val < 0 or val > 3:
                skipped += 1
            else:
                if i in reverse_items:
                    answers.append(3 - val)
                else:
                    answers.append(val)

        if skipped >= 2:
            totals.append(None)
            prorateds.append(None)
        elif skipped == 1:
            raw_val = (sum(answers) * 10.0) / 9.0
            tot = int(np.floor(raw_val + 0.5))
            totals.append(tot)
            prorateds.append(True)
        else:
            tot = sum(answers)
            totals.append(tot)
            prorateds.append(False)

    return pd.DataFrame({
        'rses_total': totals,
        'rses_prorated': prorateds
    })

my_phq9 = score_phq9(raw)
my_gad7 = score_gad7(raw)
my_rses = score_rses(raw)

my_out = pd.concat([raw[['respondent_id']], my_phq9, my_gad7, my_rses], axis=1)

for col in out.columns:
    if col == 'respondent_id':
        continue
    mismatches = (out[col].values != my_out[col].values)
    print(f"Column {col}: {mismatches.sum()} mismatches")
    if mismatches.sum() > 0:
        diff_df = pd.DataFrame({
            'id': raw['respondent_id'][mismatches],
            'pipeline': out[col][mismatches],
            'mine': my_out[col][mismatches]
        })
        print(diff_df.head(10))
